import { list_Customer_Transaction } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import { formatdisplayDate } from "@/JsonFiles/DateFormate.js";
import YouGaveCustomer from "./YouGaveCustomer.vue";
import CustomerTransactionView from "./CustomerTransactionView.vue";
export default {
  props: {
    transactionList: Boolean,
    customerDetails: Object
  },
  components: {
    YouGaveCustomer,
    CustomerTransactionView
  },
  data() {
    return {
      customerLoading: false,
      customerData: [],
      getbalance: "",
      cardValue: 1,
      itemValue: {},
      Give_Got_Type: "",
      TransactionDetails: {},
      cardHeight: 0
    };
  },
  mounted() {
    this.cardHeight = window.innerHeight - 115;
  },
  watch: {
    transactionList: {
      async handler() {
        if (this.transactionList) {
          await this.getCustomers();
        }
      },
      immediate: true
    }
  },
  computed: {
    balanceText() {
      if (this.getbalance === 0) {
        return `₹ 0`;
      }
      return this.getbalance < 0 ? `You will get: ₹ ${Math.abs(this.getbalance)}` : `You will give: ₹ ${this.getbalance}`;
    },
    balanceColor() {
      if (this.getbalance === 0) {
        return "black";
      }
      return this.getbalance < 0 ? "red" : "green";
    },
    iconName() {
      if (this.getbalance === 0) {
        return "";
      }
      return this.getbalance < 0 ? "mdi-arrow-bottom-left" : "mdi-arrow-top-right";
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.getbalance = 0;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.$emit("youGaveTransaction", "success");
      this.customerData = [];
      this.cardValue = 1;
      this.getCustomers();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    formatTimestamp(unixTimestamp) {
      if (!unixTimestamp) return "";
      const date = new Date(unixTimestamp * 1000);
      return date.toLocaleString("en-US", {
        hour: "numeric",
        minute: "numeric",
        hour12: true
      });
    },
    get_updatedate(date) {
      if (date != "" && date != undefined) {
        return formatdisplayDate(date);
      }
    },
    async getCustomers() {
      this.customerLoading = true;
      this.customerData = [];
      try {
        let result = await API.graphql(graphqlOperation(list_Customer_Transaction, {
          input: {
            customer_id: this.customerDetails.customer.customer_id
          }
        }));
        var response = JSON.parse(result.data.list_Customer_Transaction);
        this.customerLoading = false;
        if (response.Status == "SUCCESS") {
          this.customerData = response.data.transactions.sort((a, b) => b.transaction_timestamp - a.transaction_timestamp);
          this.getbalance = response.data.balanceDue;
          this.$emit("blanceAmount", this.getbalance);
          this.$emit("customerID", this.customerDetails.customer.customer_id);
        } else {
          this.customerData = [];
        }
      } catch (error) {
        this.customerLoading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    you_gave_Tab(item) {
      this.cardValue = 2;
      this.itemValue = this.customerDetails;
      this.Give_Got_Type = item;
    },
    backAction() {
      this.cardValue = 1;
      this.getCustomers();
    },
    View_Details(item) {
      this.TransactionDetails = item;
      this.cardValue = 3;
      this.itemValue = this.customerDetails;
    }
  }
};
